import hashlib
import itertools
import string
import time

def brute_force_hash(target_hash, max_length=4):
    """Attempt to crack a hash using brute force"""
    chars = string.ascii_lowercase + string.digits
    for length in range(1, max_length + 1):
        for attempt in itertools.product(chars, repeat=length):
            attempt_str = ''.join(attempt)
            if hashlib.md5(attempt_str.encode()).hexdigest() == target_hash:
                return attempt_str
    return None

def dictionary_attack(target_hash, wordlist_file='common_passwords.txt'):
    """Attempt to crack a hash using a dictionary attack"""
    try:
        with open(wordlist_file, 'r') as file:
            for line in file:
                password = line.strip()
                if hashlib.md5(password.encode()).hexdigest() == target_hash:
                    return password
    except FileNotFoundError:
        print(f"Wordlist file {wordlist_file} not found")
    return None

